242: 
243:   // Remove qualquer canal anterior com mesmo prefixo para evitar conflito de callbacks após subscribe
244:   try {
245:     const canaisExistentes = supabase.getChannels();
246:     for (const c of canaisExistentes) {
247:       if (c.topic.includes("mudancas-reservas-realtime")) {
248:         void supabase.removeChannel(c);
249:       }
250:     }
251:   } catch (err) {
252:     console.warn("[Supabase] Aviso ao limpar canais anteriores:", err);
253:   }
254: 
255:   const canalId = `mudancas-reservas-realtime-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
256:   const canal = supabase
257:     .channel(canalId)
258:     .on(
259:       "postgres_changes",
260:       {
261:         event: "INSERT",
262:         schema: "public",
263:         table: TABELA_RESERVAS,
264:       },
265:       (payload) => {
266:         const nova = rowToReserva(payload.new as ReservaDbRow);
267:         onInsert(nova);
268:       }
269:     )
270:     .on(
271:       "postgres_changes",
272:       {
273:         event: "UPDATE",
274:         schema: "public",
275:         table: TABELA_RESERVAS,
276:       },
277:       (payload) => {
278:         const atualizada = rowToReserva(payload.new as ReservaDbRow);
279:         onUpdate(atualizada);
280:       }
281:     )
282:     .on(
283:       "postgres_changes",
284:       {
285:         event: "DELETE",
286:         schema: "public",
287:         table: TABELA_RESERVAS,
288:       },
289:       (payload) => {
