51:       const parsed = JSON.parse(row.horarios);
52:       if (Array.isArray(parsed)) {
53:         horariosArray = parsed;
54:       }
55:     } catch {
56:       horariosArray = row.horarios.replace(/[{}]/g, "").split(",").map((s) => s.trim()).filter(Boolean);
57:     }
58:   }
59: 
60:   const horaInicio =
61:     row.hora_inicio ??
62:     row.horaInicio ??
63:     (horariosArray.length > 0 ? horariosArray[0] : "08:00");
64: 
65:   const horaFim =
66:     row.hora_fim ??
67:     row.horaFim ??
68:     (horariosArray.length > 0
69:       ? `${String(parseInt(horariosArray[horariosArray.length - 1], 10) + 1).padStart(2, "0")}:00`
70:       : "09:00");
71: 
72:   let userId = row.user_id ?? row.userId ?? undefined;
73:   const rawCpf = String(row.cpf_cliente ?? row.cpfCliente ?? "");
74:   if (!userId && rawCpf.startsWith("uid:")) {
75:     userId = rawCpf.replace("uid:", "");
76:   }
77: 
