/**
 * Tipos e Definições de Domínio para o Sistema de Vagas Abertas.
 * Permite que organizadores de partidas abram vagas para jogadores avulsos
 * e que interessados solicitem participação com total isenção de responsabilidade da arena.
 */

import type { Esporte } from "@/lib/quadras";

/**
 * Status do interesse de um jogador em participar da partida:
 * - 'pendente': O jogador clicou em "Mostrar Interesse" e aguarda contato do organizador.
 * - 'contatado': O organizador já visualizou e entrou em contato via WhatsApp.
 * - 'rejeitado': O organizador optou por não selecionar este jogador.
 */
export type StatusInteresse = "pendente" | "contatado" | "rejeitado";

/**
 * Entidade que registra a manifestação de interesse de um jogador autenticado
 * em uma reserva com vagas abertas.
 */
export interface InteresseVaga {
  /** Identificador único do interesse */
  id: string;
  /** Identificador da reserva vinculada */
  reservaId: string;
  /** Identificador do usuário que demonstrou interesse */
  usuarioId: string;
  /** Nome completo do usuário interessado */
  nomeUsuario: string;
  /** Telefone/WhatsApp com DDD do usuário interessado */
  telefoneUsuario: string;
  /** Status atual da tratativa */
  status: StatusInteresse;
  /** Data e hora em formato ISO da manifestação de interesse */
  criadoEm: string;
}

/**
 * Dados necessários para o organizador abrir ou atualizar as vagas de sua reserva.
 */
export interface DadosAberturaVagas {
  /** Identificador da reserva a ser modificada */
  reservaId: string;
  /** Quantidade de vagas disponíveis para novos jogadores (mínimo 1) */
  vagasAbertas: number;
  /** Confirmação obrigatória de leitura e aceite dos termos de responsabilidade */
  aceitouTermos: boolean;
}

/**
 * Dados necessários para um jogador demonstrar interesse em uma vaga aberta.
 */
export interface DadosInteresseVaga {
  /** Identificador da reserva alvo */
  reservaId: string;
  /** Identificador do usuário interessado */
  usuarioId: string;
  /** Nome do usuário interessado */
  nomeUsuario: string;
  /** Telefone de contato do interessado */
  telefoneUsuario: string;
  /** Confirmação obrigatória do termo de isenção de responsabilidade */
  aceitouTermos: boolean;
}

/**
 * Modelo enriquecido de uma vaga disponível exibida no "Mural de Vagas".
 * Reúne informações da quadra, horário, organizador e contagem de vagas.
 */
export interface VagaDisponivelItem {
  /** ID da reserva correspondente */
  reservaId: string;
  /** Data do agendamento (YYYY-MM-DD) */
  data: string;
  /** Horário de início (ex: '19:00') */
  horaInicio: string;
  /** Horário de término (ex: '20:00') */
  horaFim: string;
  /** Identificador da quadra */
  quadraId: string;
  /** Número da quadra para exibição */
  quadraNumero: number;
  /** Nome ou descrição da quadra */
  quadraDescricao: string;
  /** Modalidade esportiva da reserva */
  esporte?: Esporte;
  /** ID do organizador que fez a reserva */
  organizadorId?: string;
  /** Primeiro nome ou nome completo do organizador */
  organizadorNome: string;
  /** Quantidade atual de vagas ainda abertas */
  vagasAbertas: number;
  /** Quantidade total de pessoas que já demonstraram interesse */
  totalInteressados: number;
}

/**
 * Termo legal rigoroso de isenção de responsabilidade para o organizador.
 * O organizador deve aceitar este termo ao habilitar vagas.
 */
export const TERMO_RESPONSABILIDADE_ORGANIZADOR =
  "Ao abrir vagas para sua reserva, você declara estar ciente de que a organização, " +
  "seleção de participantes, cobrança de valores (rateio) e qualquer conduta ou dano " +
  "causado pelos convidados são de sua inteira e exclusiva responsabilidade. " +
  "A Arena e a plataforma Reservei não intermedeiam pagamentos de rateio, não realizam " +
  "triagem de jogadores e não se responsabilizam por faltas, calotes, lesões, brigas ou qualquer " +
  "outro incidente decorrente deste convite. O gerenciamento destas vagas é de sua total responsabilidade.";

/**
 * Termo legal rigoroso de isenção de responsabilidade para o interessado.
 * O jogador deve aceitar este termo ao solicitar participação.
 */
export const TERMO_RESPONSABILIDADE_INTERESSADO =
  "Ao demonstrar interesse nesta vaga, seu número de telefone/WhatsApp será compartilhado " +
  "com o organizador da partida, que poderá entrar em contato com você. O rateio de valores " +
  "e as regras do jogo são combinados diretamente com o organizador. A Arena e a plataforma " +
  "Reservei não têm qualquer envolvimento ou responsabilidade sobre cobranças, qualidade do jogo, " +
  "cancelamentos por parte do organizador ou eventuais incidentes. O acordo é feito exclusivamente entre você e o organizador.";

/**
 * Serviço de Regras de Negócio e Validações do Sistema de Vagas Abertas.
 * Funções puras e isoladas para facilitar testes unitários abrangentes e alta manutenibilidade.
 */

import type { Reserva } from "@/store/useReservasStore";
import { QUADRAS } from "@/lib/quadras";
import { getHoje } from "@/lib/constants";
import type {
  DadosAberturaVagas,
  DadosInteresseVaga,
  InteresseVaga,
  VagaDisponivelItem,
} from "./types";

/**
 * Valida a abertura ou atualização de vagas por parte do organizador de uma reserva.
 *
 * @param dados Dados informados pelo organizador
 * @param reserva Objeto da reserva a ser modificada
 * @returns Objeto com indicador de validade e lista de mensagens de erro
 *
 * @example
 * ```ts
 * const validacao = validarAberturaVagas({ reservaId: "r1", vagasAbertas: 3, aceitouTermos: true }, reserva);
 * if (!validacao.valido) console.error(validacao.erros);
 * ```
 */
export function validarAberturaVagas(
  dados: DadosAberturaVagas,
  reserva?: Reserva
): { valido: boolean; erros: string[] } {
  const erros: string[] = [];

  if (!reserva) {
    erros.push("Reserva não encontrada.");
    return { valido: false, erros };
  }

  if (reserva.status === "cancelada") {
    erros.push("Não é possível abrir vagas para uma reserva cancelada.");
  }

  const hoje = getHoje();
  if (reserva.data < hoje) {
    erros.push("Não é possível abrir vagas para reservas em datas passadas.");
  }

  if (
    !Number.isInteger(dados.vagasAbertas) ||
    dados.vagasAbertas < 1 ||
    dados.vagasAbertas > 30
  ) {
    erros.push("O número de vagas abertas deve ser um valor inteiro entre 1 e 30.");
  }

  if (!dados.aceitouTermos) {
    erros.push(
      "É obrigatório concordar com os termos de responsabilidade e rateio para abrir vagas."
    );
  }

  return {
    valido: erros.length === 0,
    erros,
  };
}

/**
 * Valida a solicitação de participação de um jogador em uma reserva com vagas abertas.
 *
 * @param dados Dados da solicitação de interesse do jogador
 * @param reserva Objeto da reserva em que o jogador quer participar
 * @param interessesExistentes Lista com os interesses já registrados no sistema
 * @returns Objeto com indicador de validade e lista de erros
 */
export function validarDemonstracaoInteresse(
  dados: DadosInteresseVaga,
  reserva?: Reserva,
  interessesExistentes: InteresseVaga[] = []
): { valido: boolean; erros: string[] } {
  const erros: string[] = [];

  if (!reserva) {
    erros.push("Reserva não encontrada.");
    return { valido: false, erros };
  }

  if (reserva.status === "cancelada") {
    erros.push("Esta reserva foi cancelada e não aceita mais participantes.");
  }

  const hoje = getHoje();
  if (reserva.data < hoje) {
    erros.push("Não é possível manifestar interesse em horários já encerrados.");
  }

  if (!reserva.permiteVagas || (reserva.vagasAbertas ?? 0) <= 0) {
    erros.push("Esta reserva não possui vagas abertas no momento.");
  }

  if (!dados.usuarioId || dados.usuarioId.trim() === "") {
    erros.push("É necessário estar autenticado para demonstrar interesse.");
  }

  if (reserva.userId && reserva.userId === dados.usuarioId) {
    erros.push("Você não pode solicitar vaga na sua própria reserva.");
  }

  const jaTemInteresse = interessesExistentes.some(
    (i) =>
      i.reservaId === dados.reservaId &&
      i.usuarioId === dados.usuarioId &&
      i.status !== "rejeitado"
  );

  if (jaTemInteresse) {
    erros.push("Você já manifestou interesse nesta vaga anteriormente.");
  }

  if (!dados.nomeUsuario || dados.nomeUsuario.trim().length < 2) {
    erros.push("Nome do usuário inválido.");
  }

  const digitosTelefone = (dados.telefoneUsuario || "").replace(/\D/g, "");
  if (digitosTelefone.length < 8) {
    erros.push("Número de WhatsApp/telefone inválido para contato.");
  }

  if (!dados.aceitouTermos) {
    erros.push(
      "É obrigatório aceitar o termo de responsabilidade para enviar seu contato ao organizador."
    );
  }

  return {
    valido: erros.length === 0,
    erros,
  };
}

/**
 * Constrói o objeto de registro de interesse após validação bem-sucedida.
 *
 * @param dados Dados validados do interesse
 * @returns Instância de InteresseVaga com ID e timestamp
 */
export function construirInteresseVaga(dados: DadosInteresseVaga): InteresseVaga {
  return {
    id: `int_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    reservaId: dados.reservaId,
    usuarioId: dados.usuarioId,
    nomeUsuario: dados.nomeUsuario.trim(),
    telefoneUsuario: dados.telefoneUsuario.trim(),
    status: "pendente",
    criadoEm: new Date().toISOString(),
  };
}

/**
 * Converte e filtra a lista de reservas ativas em itens prontos para exibição no Mural de Vagas.
 *
 * @param reservas Todas as reservas da plataforma
 * @param interesses Lista de todos os interesses registrados
 * @param dataReferencia Data base (padrão é o dia de hoje)
 * @returns Lista ordenada de vagas abertas disponíveis
 */
export function montarVagasDisponiveis(
  reservas: Reserva[],
  interesses: InteresseVaga[] = [],
  dataReferencia?: string
): VagaDisponivelItem[] {
  const baseData = dataReferencia || getHoje();

  const reservasComVagas = reservas.filter(
    (r) =>
      r.permiteVagas === true &&
      (r.vagasAbertas ?? 0) > 0 &&
      r.status !== "cancelada" &&
      r.data >= baseData
  );

  return reservasComVagas
    .map((r) => {
      const quadra = QUADRAS.find((q) => q.id === r.quadraId);
      const totalInteressados = interesses.filter(
        (i) => i.reservaId === r.id
      ).length;

      return {
        reservaId: r.id,
        data: r.data,
        horaInicio: r.horaInicio,
        horaFim: r.horaFim,
        quadraId: r.quadraId,
        quadraNumero: quadra?.numero ?? 1,
        quadraDescricao: quadra?.descricao ?? `Quadra ${quadra?.numero || 1}`,
        esporte: r.esporte,
        organizadorId: r.userId,
        organizadorNome: r.nomeCliente || "Organizador",
        vagasAbertas: r.vagasAbertas ?? 0,
        totalInteressados,
      };
    })
    .sort((a, b) => {
      if (a.data !== b.data) {
        return a.data.localeCompare(b.data);
      }
      return a.horaInicio.localeCompare(b.horaInicio);
    });
}

/**
 * Retorna os interessados em uma reserva específica, ordenados por data de manifestação.
 *
 * @param reservaId Identificador da reserva
 * @param interesses Lista geral de interesses
 * @returns Lista filtrada e ordenada de interessados
 */
export function obterInteressadosDaReserva(
  reservaId: string,
  interesses: InteresseVaga[]
): InteresseVaga[] {
  return interesses
    .filter((i) => i.reservaId === reservaId)
    .sort((a, b) => new Date(b.criadoEm).getTime() - new Date(a.criadoEm).getTime());
}

/**
 * Retorna a quantidade de interessados pendentes de contato para uma reserva.
 * Utilizado para badges de notificação visual.
 *
 * @param reservaId Identificador da reserva
 * @param interesses Lista geral de interesses
 * @returns Quantidade de interessados pendentes
 */
export function contarInteressadosPendentes(
  reservaId: string,
  interesses: InteresseVaga[]
): number {
  return interesses.filter(
    (i) => i.reservaId === reservaId && i.status === "pendente"
  ).length;
}

/**
 * Camada de persistência para o Sistema de Vagas com Supabase e Fallback LocalStorage.
 * Garante sincronização bidirecional em ambientes de produção e suporte completo offline/local.
 */

import { supabase, isSupabaseConfigured } from "./client";
import type { InteresseVaga, StatusInteresse } from "@/lib/vagas/types";

const TABELA_INTERESSES = "interesses_vagas";
const STORAGE_INTERESSES_KEY = "reservei_interesses_vagas";

interface InteresseDbRow {
  id: string;
  reserva_id: string;
  reservaId?: string;
  usuario_id: string;
  usuarioId?: string;
  nome_usuario: string;
  nomeUsuario?: string;
  telefone_usuario: string;
  telefoneUsuario?: string;
  status: string;
  created_at?: string;
  criado_em?: string;
  criadoEm?: string;
}

/**
 * Converte linha do banco para a entidade de domínio InteresseVaga.
 */
function rowToInteresse(row: InteresseDbRow): InteresseVaga {
  return {
    id: row.id,
    reservaId: row.reserva_id ?? row.reservaId ?? "",
    usuarioId: row.usuario_id ?? row.usuarioId ?? "",
    nomeUsuario: row.nome_usuario ?? row.nomeUsuario ?? "",
    telefoneUsuario: row.telefone_usuario ?? row.telefoneUsuario ?? "",
    status: (row.status as StatusInteresse) || "pendente",
    criadoEm:
      row.created_at ??
      row.criado_em ??
      row.criadoEm ??
      new Date().toISOString(),
  };
}

/**
 * Converte entidade de domínio para payload do Supabase.
 */
function interesseToRow(item: Partial<InteresseVaga>): Record<string, unknown> {
  const row: Record<string, unknown> = {};
  if (item.id !== undefined) row.id = item.id;
  if (item.reservaId !== undefined) row.reserva_id = item.reservaId;
  if (item.usuarioId !== undefined) row.usuario_id = item.usuarioId;
  if (item.nomeUsuario !== undefined) row.nome_usuario = item.nomeUsuario;
  if (item.telefoneUsuario !== undefined) row.telefone_usuario = item.telefoneUsuario;
  if (item.status !== undefined) row.status = item.status;
  if (item.criadoEm !== undefined) row.created_at = item.criadoEm;
  return row;
}

/**
 * Obtém todos os interesses armazenados no LocalStorage.
 */
export function getInteressesLocais(): InteresseVaga[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = localStorage.getItem(STORAGE_INTERESSES_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

/**
 * Salva a lista de interesses no LocalStorage.
 */
export function saveInteressesLocais(lista: InteresseVaga[]): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(STORAGE_INTERESSES_KEY, JSON.stringify(lista));
  } catch (err) {
    console.error("[Vagas] Erro ao salvar interesses no LocalStorage:", err);
  }
}

/**
 * Busca todos os interesses registrados no Supabase, com fallback para o LocalStorage.
 */
export async function fetchInteressesVagasSupabase(): Promise<InteresseVaga[]> {
  const locais = getInteressesLocais();

  if (!isSupabaseConfigured()) {
    return locais;
  }

  try {
    const { data, error } = await supabase
      .from(TABELA_INTERESSES)
      .select("*")
      .order("created_at", { ascending: false });

    if (error) {
      console.warn(
        "[Supabase Vagas] Tabela não disponível ou erro de consulta, usando local:",
        error.message
      );
      return locais;
    }

    if (data && Array.isArray(data)) {
      const mapeados = (data as InteresseDbRow[]).map(rowToInteresse);
      saveInteressesLocais(mapeados);
      return mapeados;
    }

    return locais;
  } catch (err) {
    console.warn("[Supabase Vagas] Falha inesperada ao buscar interesses:", err);
    return locais;
  }
}

/**
 * Registra um novo interesse tanto localmente quanto no Supabase.
 */
export async function inserirInteresseVagaSupabase(
  interesse: InteresseVaga
): Promise<boolean> {
  // Salva no LocalStorage imediatamente
  const locais = getInteressesLocais();
  const index = locais.findIndex((i) => i.id === interesse.id);
  if (index >= 0) {
    locais[index] = interesse;
  } else {
    locais.unshift(interesse);
  }
  saveInteressesLocais(locais);

  if (!isSupabaseConfigured()) {
    return true;
  }

  try {
    const row = interesseToRow(interesse);
    const { error } = await supabase.from(TABELA_INTERESSES).insert([row]);

    if (error) {
      console.warn(
        "[Supabase Vagas] Erro ao persistir interesse na nuvem:",
        error.message
      );
      return false;
    }

    return true;
  } catch (err) {
    console.error("[Supabase Vagas] Falha ao inserir interesse:", err);
    return false;
  }
}

/**
 * Atualiza o status de um interesse (ex: para 'contatado' ou 'rejeitado').
 */
export async function atualizarStatusInteresseSupabase(
  id: string,
  status: StatusInteresse
): Promise<boolean> {
  // Atualiza LocalStorage
  const locais = getInteressesLocais();
  const index = locais.findIndex((i) => i.id === id);
  if (index >= 0) {
    locais[index] = { ...locais[index], status };
    saveInteressesLocais(locais);
  }

  if (!isSupabaseConfigured()) {
    return true;
  }

  try {
    const { error } = await supabase
      .from(TABELA_INTERESSES)
      .update({ status })
      .eq("id", id);

    if (error) {
      console.warn(
        `[Supabase Vagas] Erro ao atualizar status do interesse ${id}:`,
        error.message
      );
      return false;
    }

    return true;
  } catch (err) {
    console.error("[Supabase Vagas] Falha ao atualizar interesse:", err);
    return false;
  }
}

/**
 * Remove todos os interesses vinculados a uma reserva cancelada ou excluída.
 */
export async function removerInteressesPorReservaSupabase(
  reservaId: string
): Promise<boolean> {
  const locais = getInteressesLocais().filter((i) => i.reservaId !== reservaId);
  saveInteressesLocais(locais);

  if (!isSupabaseConfigured()) {
    return true;
  }

  try {
    const { error } = await supabase
      .from(TABELA_INTERESSES)
      .delete()
      .eq("reserva_id", reservaId);

    if (error) {
      console.warn(
        `[Supabase Vagas] Erro ao remover interesses da reserva ${reservaId}:`,
        error.message
      );
      return false;
    }

    return true;
  } catch (err) {
    console.error("[Supabase Vagas] Falha ao remover interesses:", err);
    return false;
  }
}

