/**
 * Hook customizado de abstração para gerenciamento do Sistema de Vagas Abertas.
 * Conecta componentes de interface às regras de negócio e à camada de persistência.
 */

"use client";

import { useState, useEffect, useCallback, useMemo } from "react";
import { useReservasService } from "@/hooks/useReservasService";
import {
  validarAberturaVagas,
  validarDemonstracaoInteresse,
  construirInteresseVaga,
  montarVagasDisponiveis,
  obterInteressadosDaReserva,
  contarInteressadosPendentes,
} from "@/lib/vagas/vagasService";
import {
  fetchInteressesVagasSupabase,
  inserirInteresseVagaSupabase,
  atualizarStatusInteresseSupabase,
  getInteressesLocais,
} from "@/lib/supabase/vagasService";
import type {
  InteresseVaga,
  StatusInteresse,
  VagaDisponivelItem,
  DadosAberturaVagas,
  DadosInteresseVaga,
} from "@/lib/vagas/types";

export function useVagasService() {
  const { reservas, atualizarVagasReserva } = useReservasService();
  const [interesses, setInteresses] = useState<InteresseVaga[]>(() => getInteressesLocais());
  const [carregando, setCarregando] = useState<boolean>(true);

  // Carregamento inicial de interesses da persistência
  useEffect(() => {
    let ativo = true;

    async function carregarInteresses() {
      try {
        const dados = await fetchInteressesVagasSupabase();
        if (ativo && dados) {
          setInteresses(dados);
        }
      } catch (err) {
        console.error("[useVagasService] Erro ao carregar interesses:", err);
      } finally {
        if (ativo) {
          setCarregando(false);
        }
      }
    }

    void carregarInteresses();

    return () => {
      ativo = false;
    };
  }, []);

  /**
   * Lista enriquecida de todas as partidas ativas que possuem vagas abertas.
   * Atualizada reativamente quando o estado de reservas ou interesses muda.
   */
  const vagasDisponiveis: VagaDisponivelItem[] = useMemo(() => {
    return montarVagasDisponiveis(reservas, interesses);
  }, [reservas, interesses]);

  /**
   * Abre vagas para uma reserva existente ou atualiza a quantidade disponível.
   */
  const abrirVagas = useCallback(
    async (
      reservaId: string,
      vagasAbertas: number,
      aceitouTermos: boolean
    ): Promise<{ sucesso: boolean; erro?: string }> => {
      const reserva = reservas.find((r) => r.id === reservaId);
      const payload: DadosAberturaVagas = {
        reservaId,
        vagasAbertas,
        aceitouTermos,
      };

      const validacao = validarAberturaVagas(payload, reserva);
      if (!validacao.valido) {
        return { sucesso: false, erro: validacao.erros[0] };
      }

      try {
        atualizarVagasReserva(reservaId, true, vagasAbertas);
        return { sucesso: true };
      } catch (err) {
        console.error("[useVagasService] Falha ao abrir vagas:", err);
        return { sucesso: false, erro: "Erro inesperado ao salvar alterações." };
      }
    },
    [reservas, atualizarVagasReserva]
  );

  /**
   * Encerra a abertura de vagas de uma reserva, desativando a busca por novos participantes.
   */
  const fecharVagas = useCallback(
    async (reservaId: string): Promise<{ sucesso: boolean; erro?: string }> => {
      const reserva = reservas.find((r) => r.id === reservaId);
      if (!reserva) {
        return { sucesso: false, erro: "Reserva não encontrada." };
      }

      try {
        atualizarVagasReserva(reservaId, false, 0);
        return { sucesso: true };
      } catch (err) {
        console.error("[useVagasService] Falha ao fechar vagas:", err);
        return { sucesso: false, erro: "Não foi possível fechar as vagas." };
      }
    },
    [reservas, atualizarVagasReserva]
  );

  /**
   * Altera diretamente a contagem de vagas restantes para uma reserva com vagas já abertas.
   */
  const atualizarQuantidadeVagas = useCallback(
    async (
      reservaId: string,
      novaQuantidade: number
    ): Promise<{ sucesso: boolean; erro?: string }> => {
      const reserva = reservas.find((r) => r.id === reservaId);
      if (!reserva) {
        return { sucesso: false, erro: "Reserva não encontrada." };
      }

      if (novaQuantidade <= 0) {
        atualizarVagasReserva(reservaId, false, 0);
        return { sucesso: true };
      }

      if (!Number.isInteger(novaQuantidade) || novaQuantidade > 30) {
        return { sucesso: false, erro: "Quantidade de vagas inválida." };
      }

      atualizarVagasReserva(reservaId, true, novaQuantidade);
      return { sucesso: true };
    },
    [reservas, atualizarVagasReserva]
  );

  /**
   * Registra a manifestação de interesse de um jogador autenticado em participar de uma partida.
   */
  const demonstrarInteresse = useCallback(
    async (dados: DadosInteresseVaga): Promise<{ sucesso: boolean; erro?: string }> => {
      const reserva = reservas.find((r) => r.id === dados.reservaId);
      const validacao = validarDemonstracaoInteresse(dados, reserva, interesses);

      if (!validacao.valido) {
        return { sucesso: false, erro: validacao.erros[0] };
      }

      try {
        const novoInteresse = construirInteresseVaga(dados);
        setInteresses((prev) => [novoInteresse, ...prev]);
        await inserirInteresseVagaSupabase(novoInteresse);
        return { sucesso: true };
      } catch (err) {
        console.error("[useVagasService] Falha ao registrar interesse:", err);
        return { sucesso: false, erro: "Ocorreu um erro ao enviar sua solicitação." };
      }
    },
    [reservas, interesses]
  );

  /**
   * Atualiza o status de contato com um interessado (ex.: marcado como contatado ou rejeitado).
   */
  const atualizarStatusInteresse = useCallback(
    async (
      interesseId: string,
      status: StatusInteresse
    ): Promise<{ sucesso: boolean }> => {
      try {
        setInteresses((prev) =>
          prev.map((i) => (i.id === interesseId ? { ...i, status } : i))
        );
        await atualizarStatusInteresseSupabase(interesseId, status);
        return { sucesso: true };
      } catch (err) {
        console.error("[useVagasService] Erro ao atualizar status:", err);
        return { sucesso: false };
      }
    },
    []
  );

  /**
   * Retorna os interessados em uma reserva específica.
   */
  const getInteressadosReserva = useCallback(
    (reservaId: string): InteresseVaga[] => {
      return obterInteressadosDaReserva(reservaId, interesses);
    },
    [interesses]
  );

  /**
   * Verifica se determinado usuário já registrou interesse ativo em uma reserva.
   */
  const temInteresseRegistrado = useCallback(
    (reservaId: string, usuarioId?: string): boolean => {
      if (!usuarioId) return false;
      return interesses.some(
        (i) =>
          i.reservaId === reservaId &&
          i.usuarioId === usuarioId &&
          i.status !== "rejeitado"
      );
    },
    [interesses]
  );

  /**
   * Retorna a quantidade de interessados pendentes para gerar badges de notificação.
   */
  const getTotalNovosInteressados = useCallback(
    (reservaId: string): number => {
      return contarInteressadosPendentes(reservaId, interesses);
    },
    [interesses]
  );

  return {
    interesses,
    vagasDisponiveis,
    carregando,
    abrirVagas,
    fecharVagas,
    atualizarQuantidadeVagas,
    demonstrarInteresse,
    atualizarStatusInteresse,
    getInteressadosReserva,
    temInteresseRegistrado,
    getTotalNovosInteressados,
  };
}

/**
 * ModalGerenciarVagas — Gerenciamento de vagas abertas pelo Organizador da Reserva.
 * Permite abrir/fechar vagas, atualizar a quantidade, aceitar os termos legais
 * e visualizar/contatar a lista de jogadores interessados.
 */

"use client";

import React, { useState, useEffect } from "react";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Users,
  AlertTriangle,
  MessageCircle,
  CheckCircle2,
  XCircle,
  Plus,
  Minus,
  ShieldAlert,
  Clock,
  Calendar,
} from "lucide-react";
import type { Reserva } from "@/store/useReservasStore";
import { useVagasService } from "@/hooks/useVagasService";
import { TERMO_RESPONSABILIDADE_ORGANIZADOR } from "@/lib/vagas/types";
import { formatarDataExibicao, mascaraWhatsApp } from "@/lib/constants";
import { QUADRAS } from "@/lib/quadras";

interface ModalGerenciarVagasProps {
  open: boolean;
  onClose: () => void;
  reserva: Reserva;
}

export function ModalGerenciarVagas({
  open,
  onClose,
  reserva,
}: ModalGerenciarVagasProps) {
  const {
    abrirVagas,
    fecharVagas,
    atualizarQuantidadeVagas,
    getInteressadosReserva,
    atualizarStatusInteresse,
  } = useVagasService();

  const [quantidadeVagas, setQuantidadeVagas] = useState<number>(
    reserva.vagasAbertas && reserva.vagasAbertas > 0 ? reserva.vagasAbertas : 2
  );
  const [aceitouTermos, setAceitouTermos] = useState<boolean>(false);
  const [salvando, setSalvando] = useState<boolean>(false);

  // Sincroniza estado inicial ao abrir modal
  useEffect(() => {
    if (open) {
      setQuantidadeVagas(
        reserva.vagasAbertas && reserva.vagasAbertas > 0 ? reserva.vagasAbertas : 2
      );
      setAceitouTermos(reserva.permiteVagas || false);
    }
  }, [open, reserva]);

  const interessados = getInteressadosReserva(reserva.id);
  const quadra = QUADRAS.find((q) => q.id === reserva.quadraId);
  const estaAberto = Boolean(reserva.permiteVagas && (reserva.vagasAbertas ?? 0) > 0);

  const handleSalvarVagas = async () => {
    if (!aceitouTermos) {
      toast.error("Termos obrigatórios", {
        description: "Você deve aceitar os termos de responsabilidade para abrir vagas.",
      });
      return;
    }

    setSalvando(true);
    const res = await abrirVagas(reserva.id, quantidadeVagas, aceitouTermos);
    setSalvando(false);

    if (res.sucesso) {
      toast.success("Vagas configuradas com sucesso!", {
        description: `Sua partida agora está visível no Mural com ${quantidadeVagas} vaga(s).`,
      });
      onClose();
    } else {
      toast.error(res.erro || "Não foi possível abrir as vagas.");
    }
  };

  const handleFecharVagas = async () => {
    setSalvando(true);
    const res = await fecharVagas(reserva.id);
    setSalvando(false);

    if (res.sucesso) {
      toast.info("Vagas encerradas", {
        description: "Sua partida foi removida do Mural de Vagas abertas.",
      });
      onClose();
    } else {
      toast.error(res.erro || "Erro ao encerrar vagas.");
    }
  };

  const handleDecrementarVagaPreenchida = async () => {
    const novaQtd = (reserva.vagasAbertas ?? 1) - 1;
    setSalvando(true);
    const res = await atualizarQuantidadeVagas(reserva.id, novaQtd);
    setSalvando(false);

    if (res.sucesso) {
      setQuantidadeVagas(Math.max(1, novaQtd));
      if (novaQtd <= 0) {
        toast.success("Todas as vagas foram preenchidas!", {
          description: "O anúncio da partida no Mural foi finalizado automaticamente.",
        });
        onClose();
      } else {
        toast.success("Vaga preenchida!", {
          description: `Restam agora ${novaQtd} vaga(s) aberta(s).`,
        });
      }
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="bg-slate-900 border-slate-800 text-white max-w-xl max-h-[90vh] overflow-y-auto p-6 sm:p-7 rounded-3xl shadow-2xl">
        <DialogHeader>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 text-emerald-400 flex items-center justify-center font-bold">
              <Users className="w-5 h-5" />
            </div>
            <div>
              <DialogTitle className="text-lg font-black text-white tracking-tight">
                Gerenciar Vagas da Partida
              </DialogTitle>
              <DialogDescription className="text-xs text-slate-400 mt-0.5">
                Convide jogadores da plataforma para completar seu time
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        {/* Resumo da Partida */}
        <div className="bg-slate-850/80 border border-slate-800/90 rounded-2xl p-4 mt-2 grid grid-cols-2 gap-3 text-xs">
          <div>
            <span className="text-slate-500 text-[10px] uppercase font-bold block">
              Quadra
            </span>
            <span className="font-semibold text-white">
              Quadra {quadra?.numero || "1"} ({reserva.esporte || "Esporte"})
            </span>
          </div>
          <div>
            <span className="text-slate-500 text-[10px] uppercase font-bold block">
              Data e Horário
            </span>
            <div className="flex items-center gap-1.5 text-slate-300 font-semibold mt-0.5">
              <Calendar className="w-3.5 h-3.5 text-emerald-400" />
              <span>{formatarDataExibicao(reserva.data)}</span>
            </div>
            <div className="flex items-center gap-1.5 text-slate-400 text-[11px] mt-0.5">
              <Clock className="w-3 h-3 text-slate-500" />
              <span>
                {reserva.horaInicio} às {reserva.horaFim}
              </span>
            </div>
          </div>
        </div>

        {/* Status Atual e Controle de Vagas */}
        <div className="space-y-4 pt-3 border-t border-slate-800">
          <div className="flex items-center justify-between">
            <Label className="text-xs font-bold text-slate-200 uppercase tracking-wider">
              Quantidade de Vagas Abertas
            </Label>
            <span
              className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold ${
                estaAberto
                  ? "bg-emerald-500/20 text-emerald-300 border border-emerald-500/30"
                  : "bg-slate-800 text-slate-400 border border-slate-700"
              }`}
            >
              {estaAberto ? `${reserva.vagasAbertas} vaga(s) ativa(s)` : "Vagas Fechadas"}
            </span>
          </div>

          <div className="flex items-center gap-3">
            <Button
              type="button"
              variant="outline"
              size="icon"
              disabled={quantidadeVagas <= 1 || salvando}
              onClick={() => setQuantidadeVagas((prev) => Math.max(1, prev - 1))}
              className="border-slate-700 bg-slate-800 text-white hover:bg-slate-700 h-10 w-10 rounded-xl"
            >
              <Minus className="w-4 h-4" />
            </Button>

            <div className="flex-1 bg-slate-950 border border-slate-800 rounded-xl h-10 flex items-center justify-center font-black text-lg text-emerald-400">
              {quantidadeVagas} {quantidadeVagas === 1 ? "vaga" : "vagas"}
            </div>

            <Button
              type="button"
              variant="outline"
              size="icon"
              disabled={quantidadeVagas >= 20 || salvando}
              onClick={() => setQuantidadeVagas((prev) => Math.min(20, prev + 1))}
              className="border-slate-700 bg-slate-800 text-white hover:bg-slate-700 h-10 w-10 rounded-xl"
            >
              <Plus className="w-4 h-4" />
            </Button>
          </div>

          {estaAberto && (
            <div className="flex items-center justify-between p-3 rounded-xl bg-slate-800/40 border border-slate-700/60 text-xs">
              <span className="text-slate-300">
                Acertou com alguém no WhatsApp?
              </span>
              <Button
                type="button"
                size="sm"
                variant="secondary"
                disabled={salvando}
                onClick={handleDecrementarVagaPreenchida}
                className="bg-emerald-500/15 hover:bg-emerald-500/25 text-emerald-400 border border-emerald-500/30 text-xs font-bold h-8"
              >
                Preencher 1 Vaga (-1)
              </Button>
            </div>
          )}
        </div>

        {/* Termos Legais e Isenção Obrigatória */}
        <div className="bg-amber-500/10 border border-amber-500/30 rounded-2xl p-4 text-xs space-y-3">
          <div className="flex items-start gap-2 text-amber-400 font-bold">
            <ShieldAlert className="w-4 h-4 mt-0.5 shrink-0" />
            <span>Aviso Legal e Responsabilidade da Coleta</span>
          </div>
          <p className="text-slate-300 leading-relaxed text-[11px]">
            {TERMO_RESPONSABILIDADE_ORGANIZADOR}
          </p>
          <label className="flex items-start gap-2.5 pt-2 border-t border-amber-500/20 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={aceitouTermos}
              onChange={(e) => setAceitouTermos(e.target.checked)}
              className="mt-0.5 h-4 w-4 rounded border-slate-700 bg-slate-900 text-emerald-500 focus:ring-emerald-500"
            />
            <span className="text-xs font-semibold text-white">
              Declaro que li, compreendi e assumo a responsabilidade integral pelo convite e organização.
            </span>
          </label>
        </div>

        {/* Lista de Interessados */}
        <div className="space-y-3 pt-3 border-t border-slate-800">
          <div className="flex items-center justify-between">
            <h4 className="text-xs font-bold text-slate-200 uppercase tracking-wider flex items-center gap-2">
              <MessageCircle className="w-3.5 h-3.5 text-emerald-400" />
              Interessados nesta partida ({interessados.length})
            </h4>
          </div>

          {interessados.length === 0 ? (
            <div className="bg-slate-950/60 border border-slate-800 rounded-xl p-5 text-center text-xs text-slate-400">
              Ainda não há jogadores interessados nesta partida. Assim que alguém clicar em
              "Mostrar Interesse" no Mural, o contato aparecerá aqui para você chamar!
            </div>
          ) : (
            <div className="space-y-2.5 max-h-56 overflow-y-auto pr-1">
              {interessados.map((item) => {
                const digits = item.telefoneUsuario.replace(/\D/g, "");
                const msgWhatsapp = encodeURIComponent(
                  `Olá ${item.nomeUsuario}, vi que você tem interesse na vaga da partida de ${reserva.esporte || "futebol"} no Reservei (${formatarDataExibicao(reserva.data)} às ${reserva.horaInicio}). Tudo bem?`
                );
                return (
                  <div
                    key={item.id}
                    className="p-3.5 rounded-xl bg-slate-950 border border-slate-800/90 flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs"
                  >
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-white text-sm">
                          {item.nomeUsuario}
                        </span>
                        <span
                          className={`px-2 py-0.5 rounded text-[10px] font-bold ${
                            item.status === "contatado"
                              ? "bg-emerald-500/20 text-emerald-300"
                              : item.status === "rejeitado"
                              ? "bg-red-500/20 text-red-300"
                              : "bg-amber-500/20 text-amber-300"
                          }`}
                        >
                          {item.status === "contatado"
                            ? "Contatado"
                            : item.status === "rejeitado"
                            ? "Dispensado"
                            : "Aguardando"}
                        </span>
                      </div>
                      <p className="text-slate-400 text-xs mt-0.5">
                        WhatsApp: {mascaraWhatsApp(item.telefoneUsuario)}
                      </p>
                    </div>

                    <div className="flex items-center gap-2 shrink-0">
                      <a
                        href={`https://wa.me/55${digits}?text=${msgWhatsapp}`}
                        target="_blank"
                        rel="noreferrer"
                        onClick={() => atualizarStatusInteresse(item.id, "contatado")}
                      >
                        <Button
                          size="sm"
                          className="bg-emerald-500 hover:bg-emerald-600 text-slate-950 font-bold h-8 text-xs gap-1.5"
                        >
                          <MessageCircle className="w-3.5 h-3.5" />
                          Chamar no WhatsApp
                        </Button>
                      </a>

                      {item.status === "pendente" && (
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => atualizarStatusInteresse(item.id, "contatado")}
                          title="Marcar como contatado"
                          className="text-slate-400 hover:text-emerald-400 h-8 px-2"
                        >
                          <CheckCircle2 className="w-4 h-4" />
                        </Button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Botões de Ação */}
        <div className="pt-4 border-t border-slate-800 flex flex-col sm:flex-row gap-2.5 justify-end">
          {estaAberto && (
            <Button
              type="button"
              variant="outline"
              disabled={salvando}
              onClick={handleFecharVagas}
              className="border-red-500/30 text-red-400 hover:bg-red-500/10 font-bold text-xs h-10 rounded-xl"
            >
              Fechar Vagas (Não Aceitar Mais)
            </Button>
          )}

          <Button
            type="button"
            variant="ghost"
            onClick={onClose}
            className="text-slate-400 hover:text-white text-xs h-10 rounded-xl"
          >
            Voltar
          </Button>

          <Button
            type="button"
            disabled={salvando}
            onClick={handleSalvarVagas}
            className="bg-emerald-500 hover:bg-emerald-600 text-slate-950 font-bold text-xs h-10 rounded-xl"
          >
            {salvando
              ? "Salvando..."
              : estaAberto
              ? "Atualizar Vagas"
              : "Habilitar e Publicar Vagas"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * ModalConfirmarInteresse — Confirmação e aceite de termos pelo jogador interessado.
 * Compartilha o contato do interessado com o organizador com total proteção legal para a arena.
 */

"use client";

import React, { useState } from "react";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import {
  Users,
  ShieldAlert,
  Calendar,
  Clock,
  Sparkles,
  Phone,
  CheckCircle2,
} from "lucide-react";
import type { VagaDisponivelItem } from "@/lib/vagas/types";
import { TERMO_RESPONSABILIDADE_INTERESSADO } from "@/lib/vagas/types";
import { useVagasService } from "@/hooks/useVagasService";
import { useUserAuth } from "@/hooks/useUserAuth";
import { formatarDataExibicao } from "@/lib/constants";

interface ModalConfirmarInteresseProps {
  open: boolean;
  onClose: () => void;
  vaga: VagaDisponivelItem | null;
  onSucesso?: () => void;
}

export function ModalConfirmarInteresse({
  open,
  onClose,
  vaga,
  onSucesso,
}: ModalConfirmarInteresseProps) {
  const { user } = useUserAuth();
  const { demonstrarInteresse } = useVagasService();
  const [aceitouTermos, setAceitouTermos] = useState<boolean>(false);
  const [enviando, setEnviando] = useState<boolean>(false);

  if (!vaga) return null;

  const handleConfirmar = async () => {
    if (!user) {
      toast.error("Conta necessária", {
        description: "Você precisa estar conectado à sua conta para solicitar vagas.",
      });
      return;
    }

    if (!aceitouTermos) {
      toast.error("Termo obrigatório", {
        description: "É obrigatório aceitar o termo de isenção de responsabilidade.",
      });
      return;
    }

    setEnviando(true);
    const res = await demonstrarInteresse({
      reservaId: vaga.reservaId,
      usuarioId: user.id,
      nomeUsuario: user.nome,
      telefoneUsuario: user.telefone,
      aceitouTermos,
    });
    setEnviando(false);

    if (res.sucesso) {
      toast.success("Interesse registrado com sucesso! 🎉", {
        description: `O organizador (${vaga.organizadorNome}) recebeu seu contato e te chamará no WhatsApp se a vaga for confirmada.`,
        duration: 6000,
      });
      setAceitouTermos(false);
      onClose();
      if (onSucesso) onSucesso();
    } else {
      toast.error(res.erro || "Não foi possível registrar o interesse.");
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="bg-slate-900 border-slate-800 text-white max-w-md p-6 sm:p-7 rounded-3xl shadow-2xl">
        <DialogHeader>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 text-emerald-400 flex items-center justify-center font-bold">
              <Users className="w-5 h-5" />
            </div>
            <div>
              <DialogTitle className="text-lg font-black text-white tracking-tight">
                Quero Participar do Jogo
              </DialogTitle>
              <DialogDescription className="text-xs text-slate-400 mt-0.5">
                Envie seu WhatsApp para o organizador da partida
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        {/* Detalhes da Partida */}
        <div className="bg-slate-950/80 border border-slate-800/80 rounded-2xl p-4 mt-2 space-y-2.5 text-xs">
          <div className="flex items-center justify-between">
            <span className="font-bold text-white text-sm">
              Quadra {vaga.quadraNumero} ({vaga.esporte || "Esporte"})
            </span>
            <span className="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
              {vaga.vagasAbertas} {vaga.vagasAbertas === 1 ? "vaga restante" : "vagas restantes"}
            </span>
          </div>

          <div className="grid grid-cols-2 gap-2 pt-2 border-t border-slate-800 text-slate-300 text-[11px]">
            <div className="flex items-center gap-1.5">
              <Calendar className="w-3.5 h-3.5 text-slate-400" />
              <span>{formatarDataExibicao(vaga.data)}</span>
            </div>
            <div className="flex items-center gap-1.5">
              <Clock className="w-3.5 h-3.5 text-slate-400" />
              <span>{vaga.horaInicio} às {vaga.horaFim}</span>
            </div>
          </div>

          <div className="pt-2 border-t border-slate-800 flex items-center justify-between text-[11px]">
            <span className="text-slate-400">Organizador da Partida:</span>
            <span className="font-bold text-white">{vaga.organizadorNome}</span>
          </div>
        </div>

        {/* Seus dados que serão enviados */}
        {user && (
          <div className="p-3 bg-slate-800/40 border border-slate-700/60 rounded-xl text-xs flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Phone className="w-3.5 h-3.5 text-emerald-400" />
              <span className="text-slate-300">Contato a ser enviado:</span>
            </div>
            <span className="font-bold text-white">{user.telefone}</span>
          </div>
        )}

        {/* Termos Legais do Jogador */}
        <div className="bg-amber-500/10 border border-amber-500/30 rounded-2xl p-4 text-xs space-y-2.5">
          <div className="flex items-center gap-2 text-amber-400 font-bold">
            <ShieldAlert className="w-4 h-4 shrink-0" />
            <span>Isenção de Responsabilidade da Arena</span>
          </div>
          <p className="text-slate-300 leading-relaxed text-[11px]">
            {TERMO_RESPONSABILIDADE_INTERESSADO}
          </p>
          <label className="flex items-start gap-2.5 pt-2 border-t border-amber-500/20 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={aceitouTermos}
              onChange={(e) => setAceitouTermos(e.target.checked)}
              className="mt-0.5 h-4 w-4 rounded border-slate-700 bg-slate-900 text-emerald-500 focus:ring-emerald-500"
            />
            <span className="text-xs font-semibold text-white">
              Estou ciente e concordo com o envio do meu telefone ao organizador.
            </span>
          </label>
        </div>

        <DialogFooter className="mt-3 flex gap-2">
          <Button
            type="button"
            variant="ghost"
            onClick={onClose}
            className="text-slate-400 hover:text-white text-xs h-10 rounded-xl"
          >
            Cancelar
          </Button>

          <Button
            type="button"
            disabled={enviando || !aceitouTermos}
            onClick={handleConfirmar}
            className="bg-emerald-500 hover:bg-emerald-600 text-slate-950 font-bold text-xs h-10 rounded-xl shadow-lg shadow-emerald-500/20"
          >
            {enviando ? "Registrando..." : "Confirmar e Enviar Contato"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * MuralVagasAbertas — Painel dedicado que concentra todas as vagas abertas na arena.
 * Projetado para ficar abaixo do carrinho ou no portal do cliente sem sobrecarregar a grade de horários.
 */

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import {
  Users,
  Calendar,
  Clock,
  CheckCircle2,
  Sparkles,
  ArrowRight,
  UserCheck,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { useVagasService } from "@/hooks/useVagasService";
import { useUserAuth } from "@/hooks/useUserAuth";
import { formatarDataExibicao } from "@/lib/constants";
import type { VagaDisponivelItem } from "@/lib/vagas/types";
import { ModalConfirmarInteresse } from "./ModalConfirmarInteresse";

export function MuralVagasAbertas() {
  const router = useRouter();
  const { user } = useUserAuth();
  const { vagasDisponiveis, temInteresseRegistrado } = useVagasService();
  const [vagaSelecionada, setVagaSelecionada] = useState<VagaDisponivelItem | null>(null);

  const handleAbrirInteresse = (vaga: VagaDisponivelItem) => {
    if (!user) {
      toast.info("Conta necessária para participar", {
        description: "Faça login ou crie sua conta para demonstrar interesse em partidas com vagas abertas.",
        action: {
          label: "Entrar",
          onClick: () => router.push("/login"),
        },
      });
      return;
    }

    if (vaga.organizadorId && vaga.organizadorId === user.id) {
      toast.info("Você é o organizador desta partida.");
      return;
    }

    if (temInteresseRegistrado(vaga.reservaId, user.id)) {
      toast.info("Você já manifestou interesse nesta vaga.");
      return;
    }

    setVagaSelecionada(vaga);
  };

  if (vagasDisponiveis.length === 0) {
    return (
      <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-5 text-center shadow-lg">
        <div className="w-9 h-9 rounded-xl bg-slate-800/80 text-slate-400 flex items-center justify-center mx-auto mb-2.5">
          <Users className="w-4 h-4" />
        </div>
        <h3 className="text-xs font-bold text-slate-200">
          Mural de Vagas da Galera
        </h3>
        <p className="text-[11px] text-slate-500 mt-1 max-w-xs mx-auto">
          Nenhum time precisando de jogadores no momento. Quando alguém abrir vagas, elas aparecerão aqui!
        </p>
      </div>
    );
  }

  return (
    <>
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5 shadow-xl space-y-4">
        {/* Cabeçalho do Mural */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-xl bg-gradient-to-tr from-emerald-600 to-teal-400 text-slate-950 flex items-center justify-center font-black shadow-md shadow-emerald-500/20">
              <Users className="w-4 h-4" />
            </div>
            <div>
              <h3 className="text-sm font-black text-white tracking-tight flex items-center gap-1.5">
                Vagas Abertas na Arena
                <span className="inline-flex items-center px-1.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                  {vagasDisponiveis.length}
                </span>
              </h3>
              <p className="text-[11px] text-slate-400 mt-0.5">
                Entre em partidas organizadas por outros jogadores
              </p>
            </div>
          </div>
        </div>

        {/* Lista de Vagas */}
        <div className="space-y-3">
          {vagasDisponiveis.map((vaga) => {
            const isMinhaReserva = Boolean(user && vaga.organizadorId === user.id);
            const jaDemonstrou = Boolean(user && temInteresseRegistrado(vaga.reservaId, user.id));

            return (
              <div
                key={vaga.reservaId}
                className="bg-slate-950/70 border border-slate-800/90 hover:border-slate-700/80 rounded-xl p-3.5 transition-all text-xs space-y-2.5"
              >
                <div className="flex items-start justify-between gap-2">
                  <div>
                    <span className="text-[10px] font-bold text-emerald-400 uppercase tracking-wider block">
                      Quadra {vaga.quadraNumero} · {vaga.esporte || "Esporte"}
                    </span>
                    <h4 className="font-bold text-white text-xs mt-0.5">
                      {vaga.quadraDescricao}
                    </h4>
                  </div>
                  <span className="px-2 py-0.5 rounded-md text-[10px] font-black bg-emerald-500/15 text-emerald-400 border border-emerald-500/30 shrink-0">
                    {vaga.vagasAbertas} {vaga.vagasAbertas === 1 ? "vaga" : "vagas"}
                  </span>
                </div>

                <div className="flex items-center justify-between text-[11px] text-slate-300">
                  <div className="flex items-center gap-1.5">
                    <Calendar className="w-3.5 h-3.5 text-slate-500" />
                    <span>{formatarDataExibicao(vaga.data)}</span>
                  </div>
                  <div className="flex items-center gap-1.5">
                    <Clock className="w-3.5 h-3.5 text-slate-500" />
                    <span>{vaga.horaInicio} às {vaga.horaFim}</span>
                  </div>
                </div>

                <div className="pt-2 border-t border-slate-800/60 flex items-center justify-between gap-2">
                  <span className="text-[10px] text-slate-400 truncate max-w-[120px]">
                    Org: <strong className="text-slate-300 font-semibold">{vaga.organizadorNome.split(" ")[0]}</strong>
                  </span>

                  {isMinhaReserva ? (
                    <span className="text-[11px] font-semibold text-slate-500 flex items-center gap-1">
                      <UserCheck className="w-3.5 h-3.5 text-slate-500" /> Sua partida
                    </span>
                  ) : jaDemonstrou ? (
                    <span className="text-[11px] font-bold text-emerald-400 flex items-center gap-1">
                      <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" /> Interesse enviado
                    </span>
                  ) : (
                    <Button
                      size="sm"
                      onClick={() => handleAbrirInteresse(vaga)}
                      className="bg-emerald-500 hover:bg-emerald-600 text-slate-950 font-bold text-[11px] h-7 px-3 rounded-lg shadow-sm"
                    >
                      Quero Jogar
                    </Button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Modal de confirmação para o jogador interessado */}
      <ModalConfirmarInteresse
        open={Boolean(vagaSelecionada)}
        vaga={vagaSelecionada}
        onClose={() => setVagaSelecionada(null)}
      />
    </>
  );
}

