      Vagas fechadas
    </span>
  )}

  {getTotalNovosInteressados(reserva.id) > 0 && (
    <span className="px-2.5 py-1 rounded-full text-[10px] font-bold bg-amber-500/20 text-amber-300 border border-amber-500/40 flex items-center gap-1.5">
