      }}
      className="text-xs text-red-400 hover:text-red-300 hover:underline"
    >
      Cancelar Reserva
    </button>
    <a
      href={`https://wa.me/${TELEFONE_COMPLEXO.replace(/\D/g, "")}?text=Olá,%20tenho%20uma%20dúvida%20sobre%20minha%20reserva%20no%20dia%20${reserva.data}`}
